css:
.timeline {
  margin: 0;
  padding: 16px 16px 16px 32px;
  list-style: none;
  border-left: 2px solid #a1a1aa;
}

.entry {
  position: relative;
  padding-bottom: 20px;
}

.dot {
  position: absolute;
  top: 4px;
  left: -41px; /* centred on the line */
  z-index: 1;
  width: 14px;
  height: 14px;
  border: 3px solid #fafafa;
  border-radius: 50%;
  background: #f97316;
}

.when {
  margin: 0 0 4px;
  font-weight: 600;
}

.entry p {
  margin-top: 0;
}
